<?php
namespace App\Services;
use App\Models\AuditLog; use App\Models\SystemSetting;
class AuditRetentionService { public function run(): array { $s=SystemSetting::valueFor('audit.retention',['retention_days'=>0,'max_per_run'=>1000]); $days=(int)($s['retention_days']??0); if($days<=0)return ['enabled'=>false,'pruned'=>0]; abort_unless(app(AuditIntegrityService::class)->verify()['valid']??false,409,'Audit chain verification failed; retention prune refused.'); $ids=AuditLog::query()->where('created_at','<',now()->subDays($days))->orderBy('id')->limit(max(1,(int)($s['max_per_run']??1000)))->pluck('id'); if($ids->isEmpty())return ['enabled'=>true,'pruned'=>0]; \DB::statement("SET @karyalay_audit_retention = 1"); try{$n=\DB::table('audit_logs')->whereIn('id',$ids)->delete();} finally{try{\DB::statement("SET @karyalay_audit_retention = NULL");}catch(\Throwable){}} $s['last_run_at']=now()->toIso8601String(); SystemSetting::put('audit.retention',$s); return ['enabled'=>true,'pruned'=>$n]; } }
